INSERT INTO records VALUES ('linux-CVE-2024-26581-mainline','linux','Interval garbage-collection generation-state fix','{"claims":[{"evidence_ids":["e-commit","e-before","e-after"],"id":"claim-change","status":"observed","text":"The patch changes generation-state handling during interval-end garbage collection and removes the caller-supplied generation-mask argument."},{"evidence_ids":["e-commit","e-before","e-after"],"id":"claim-lesson","status":"hypothesis","text":"Candidate defensive lesson: garbage collection must distinguish object lifetime and transaction visibility; callers should not impose a generation filter that violates interval pairing. Applicability requires checking transaction and lifetime invariants in the audited code."}],"edges":[{"evidence_ids":["e-commit"],"id":"edge-parent","known_at":"2026-10-07T03:57:50.554977+00:00","relation":"parent_of","source":"commit:f82777e8ce6c039cdcacbcf1eb8619b99a20c06d","status":"observed","target":"commit:60c0c230c6f046da536d3df8b39a20b9a9fd6af0"},{"evidence_ids":["e-commit"],"id":"edge-fixes","known_at":"2026-10-07T03:57:50.554977+00:00","relation":"fixes","source":"commit:60c0c230c6f046da536d3df8b39a20b9a9fd6af0","status":"observed","target":"commit:f718863aca469a109895cb855e6b81fff4827d71"},{"evidence_ids":["e-advisory"],"id":"edge-advisory","known_at":"2026-10-07T03:57:50.554977+00:00","relation":"fixed_by","source":"cve:CVE-2024-26581","status":"observed","target":"commit:60c0c230c6f046da536d3df8b39a20b9a9fd6af0"},{"evidence_ids":["e-before","e-commit"],"id":"edge-before","known_at":"2026-10-07T03:57:50.554977+00:00","relation":"before","source":"commit:60c0c230c6f046da536d3df8b39a20b9a9fd6af0","status":"observed","target":"code:f82777e8ce6c039cdcacbcf1eb8619b99a20c06d:net/netfilter/nft_set_rbtree.c"},{"evidence_ids":["e-after","e-commit"],"id":"edge-after","known_at":"2026-10-07T03:57:50.554977+00:00","relation":"after","source":"commit:60c0c230c6f046da536d3df8b39a20b9a9fd6af0","status":"observed","target":"