INSERT INTO record_fts VALUES ('linux-CVE-2024-26581-mainline','Interval garbage-collection generation-state fix CVE-2024-26581 netfilter: nft_set_rbtree: skip end interval element from gc Selected sole parent of fix Prior change referenced by Fixes trailer before net/netfilter/nft_set_rbtree.c nft_rbtree_gc_elem after net/netfilter/nft_set_rbtree.c nft_rbtree_gc_elem The patch changes generation-state handling during interval-end garbage collection and removes the caller-supplied generation-mask argument. Candidate defensive lesson: garbage collection must distinguish object lifetime and transaction visibility; callers should not impose a generation filter that violates interval pairing. Applicability requires checking transaction and lifetime invariants in the audited code.');
